const normalizeChordToken=c=>String(c).replace(/[.,;:]+$/,'').trim();function isSection(line){const t=line.trim().toUpperCase();return /^\[.*\]/.test(t)||/^(INTRO|VERSO|CORO|REFR|PUENTE|SOLO|1ºVERSO|2ºVERSO|3ºVERSO|PRIMEIRA PARTE|SEGUNDA PARTE|TERCEIRA PARTE)/.test(t)}function isChordToken(t){return!!CH.parseChord(normalizeChordToken(t))}function isChordLine(line){const t=line.trim();if(!t)return false;const p=t.split(/\s+/).filter(Boolean),m=p.filter(x=>!/^[-|/()\[\]xX.]+$/.test(x));return m.length>0&&m.every(isChordToken)}
function renderChordLine(line){let out='',pos=0,re=/[A-G](?:#|b)?(?:m|maj|sus|dim|aug|add)?\d*(?:\/[A-G](?:#|b)?)?\.?/g,m;while((m=re.exec(line))){out+=esc(line.slice(pos,m.index));const raw=m[0],clean=normalizeChordToken(raw);out+=`<button class="chord-link" data-chord="${esc(clean)}">${esc(displayChord(clean))}</button>${raw.endsWith('.')?'.':''}`;pos=m.index+raw.length}return out+esc(line.slice(pos))}
function renderChart(text){return text.split('\n').map(line=>isSection(line)?`<div class="line section">${esc(line)||'&nbsp;'}</div>`:isChordLine(line)?`<div class="line chord-line">${renderChordLine(line)||'&nbsp;'}</div>`:`<div class="line">${esc(line)||'&nbsp;'}</div>`).join('')}
function openSong(id,scroll=true){currentSong=songs.find(s=>s.id===id);if(!currentSong)return;showView('detail');$('songTitle').textContent=currentSong.title;$('songArtist').textContent=currentSong.artist;$('songTypeBadge').textContent=currentSong.type==='himnos'?appText('Himno','Hymn'):appText('Canto','Song');$('songTone').textContent=displayTone(currentSong.tone);$('favBtn').textContent=getFavs().includes(id)?`★ ${appText('Favorito','Favorite')}`:`☆ ${appText('Favorito','Favorite')}`;$('chart').innerHTML=renderChart(currentSong.content);$('chart').style.fontSize=fontSize+'px';$('chart').querySelectorAll('[data-chord]').forEach(b=>b.onclick=()=>openChord(b.dataset.chord));renderPersonalSongNotes(id);renderMinistrySongContext(id);if(scroll)window.scrollTo(0,0)}
function songBack(){if(songReturn.type==='setlist')showEventSetlist(songReturn.value);else if(songReturn.type==='home')home();else if(songReturn.type==='artist')showArtist(songReturn.value);else showSongList(songReturn.value||'cantos')}function toggleFavorite(){if(!currentSong)return;let a=getFavs();const had=a.includes(currentSong.id);a=had?a.filter(x=>x!==currentSong.id):[...a,currentSong.id];saveFavs(a);toast(had?appText('Quitado de favoritos','Removed from favorites'):appText('Añadido a favoritos','Added to favorites'));if(cloudState()?.mode==='ministry')syncPersonalFavorites()}function changeFont(n){fontSize=Math.max(12,Math.min(28,fontSize+n));localStorage.setItem('lagrey_font',fontSize);$('chart').style.fontSize=fontSize+'px'}
const MINISTRY_TONES=['C','C#','Db','D','D#','Eb','E','F','F#','Gb','G','G#','Ab','A','A#','Bb','B'];
let cloudStateUnsubscribe=null,repertoireSyncPromise=null;
function updateMinistryHome(){const ministryId=currentMinistryId(),card=$('ministryRepertoireCard'),count=$('repertoireCount'),title=$('repertoireTitle'),desc=$('repertoireDesc'),route=$('myRouteCard'),routeTitle=$('myRouteCardTitle'),routeDesc=$('myRouteCardDesc'),routeProgress=$('myRouteCardProgress');if(card)card.classList.toggle('hidden',!ministryId);if(route)route.classList.toggle('hidden',!ministryId);if(count)count.textContent=ministryId?`${getRepertoireRows().length} ${appText('cantos','songs')}`:'';if(title)title.textContent=appText('Repertorio','Repertoire');if(desc)desc.innerHTML=appText('Los cantos oficiales<br>de tu ministerio','The official songs<br>of your ministry');if(routeTitle)routeTitle.textContent=appText('Mi ruta','My path');if(routeDesc)routeDesc.innerHTML=appText('Prepárate paso a paso<br>para servir con tu equipo','Prepare step by step<br>to serve with your team');if(routeProgress)routeProgress.textContent=ministryId?`${myRouteDone().size}/${MY_ROUTE_STEPS.length} · ${appText('pasos','steps')}`:''}
function fillOfficialToneSelect(value){const select=$('officialToneSelect');if(!select)return;select.innerHTML=`<option value="">${appText('Sin definir','Not set')}</option>`+MINISTRY_TONES.map(t=>`<option value="${t}">${esc(displayTone(t))}</option>`).join('');select.value=MINISTRY_TONES.includes(String(value||''))?String(value):''}
async function pullMinistryRepertoire({rerender=true}={}){const state=cloudState();updateMinistryHome();if(state?.mode!=='ministry'||!state.data?.getRepertoire)return getRepertoireRows();if(repertoireSyncPromise)return repertoireSyncPromise;repertoireSyncPromise=(async()=>{const rows=await state.data.getRepertoire();saveRepertoireRows(rows);updateMinistryHome();if(rerender&&lastSongList==='repertoire'&&!$('listing')?.classList.contains('hidden'))renderSongList(currentListSongs());if(currentSong&&!$('detail')?.classList.contains('hidden'))renderMinistrySongContext(currentSong.id,{networkNotes:false});return getRepertoireRows()})().catch(error=>{console.warn('[La Grey] No se pudo actualizar el repertorio',error);updateMinistryHome();return getRepertoireRows()}).finally(()=>{repertoireSyncPromise=null});return repertoireSyncPromise}
async function renderMinistrySongContext(songId,{networkNotes=true}={}){const ministryId=currentMinistryId(),panel=$('ministrySongPanel'),button=$('repertoireBtn'),select=$('officialToneSelect'),notes=$('sharedSongNotes'),save=$('saveMinistrySongBtn'),status=$('ministrySongStatus'),help=$('ministrySongHelp');if(!panel||!button)return;if(!ministryId){button.classList.add('hidden');panel.classList.add('hidden');if(currentSong&&Number(currentSong.id)===Number(songId))$('songTone').textContent=displayTone(currentSong.tone);return}const row=repertoireRow(songId),editable=canEditMinistryRepertoire();button.classList.remove('hidden');button.disabled=!editable;button.textContent=row?`✓ ${appText('En repertorio','In repertoire')}`:editable?`＋ ${appText('Añadir al repertorio','Add to repertoire')}`:`— ${appText('Fuera del repertorio','Not in repertoire')}`;button.title=editable?'':appText('Solo propietarios, administradores y líderes pueden modificar el repertorio.','Only owners, administrators, and leaders can modify the repertoire.');if(!row){panel.classList.add('hidden');if(currentSong&&Number(currentSong.id)===Number(songId))$('songTone').textContent=displayTone(currentSong.tone);return}panel.classList.remove('hidden');if(status)status.textContent=currentMinistryName();fillOfficialToneSelect(row.officialTone||'');if(select)select.disabled=!editable;if(currentSong&&Number(currentSong.id)===Number(songId))$('songTone').textContent=displayTone(row.officialTone||currentSong.tone);const cached=String(localStorage.getItem(noteCacheKey(ministryId,songId))||'');if(notes){notes.value=cached;notes.readOnly=!editable}if(save)save.classList.toggle('hidden',!editable);if(help)help.textContent=editable?appText('Estos datos los comparte todo el ministerio.','These details are shared with the whole ministry.'):appText('Vista de solo lectura. Los líderes y administradores gestionan estos datos.','Read-only view. Leaders and administrators manage these details.');const state=cloudState();if(networkNotes&&state?.mode==='ministry'&&state.data?.getSharedSongNotes){try{const body=await state.data.getSharedSongNotes(songId);localStorage.setItem(noteCacheKey(ministryId,songId),String(body||''));if(currentSong&&Number(currentSong.id)===Number(songId)&&notes)notes.value=String(body||'')}catch(error){console.warn('[La Grey] No se pudieron cargar las notas compartidas',error)}}}
async function toggleMinistryRepertoire(){if(!currentSong)return;const state=cloudState();if(state?.mode!=='ministry'||!state.data){toast(appText('Necesitas conexión y una sesión de ministerio activa.','You need a connection and an active ministry session.'));return}if(!canEditMinistryRepertoire()){toast(appText('Solo propietarios, administradores y líderes pueden modificar el repertorio.','Only owners, administrators, and leaders can modify the repertoire.'));return}const row=repertoireRow(currentSong.id),button=$('repertoireBtn');if(row&&!confirm(appText('¿Quitar esta canción del repertorio del ministerio?','Remove this song from the ministry repertoire?')))return;if(button)button.disabled=true;try{if(row)await state.data.removeFromRepertoire(currentSong.id);else await state.data.addToRepertoire(currentSong.id);await pullMinistryRepertoire({rerender:true});await renderMinistrySongContext(currentSong.id);toast(row?appText('Quitado del repertorio del ministerio.','Removed from the ministry repertoire.'):appText('Añadido al repertorio del ministerio.','Added to the ministry repertoire.'))}catch(error){console.warn('[La Grey] No se pudo modificar el repertorio',error);toast(appText('No se pudo sincronizar el repertorio.','Could not sync the repertoire.'));renderMinistrySongContext(currentSong.id,{networkNotes:false})}}
async function saveMinistrySongDetails(){if(!currentSong||!canEditMinistryRepertoire())return;const state=cloudState(),row=repertoireRow(currentSong.id);if(state?.mode!=='ministry'||!state.data||!row){toast(appText('Esta canción debe estar en el repertorio antes de guardar.','This song must be in the repertoire before saving.'));return}const button=$('saveMinistrySongBtn'),tone=$('officialToneSelect')?.value||'',notes=$('sharedSongNotes')?.value||'';if(button)button.disabled=true;try{await Promise.all([state.data.setOfficialTone(currentSong.id,tone),state.data.saveSharedSongNotes(currentSong.id,notes)]);localStorage.setItem(noteCacheKey(currentMinistryId(),currentSong.id),notes);await pullMinistryRepertoire({rerender:true});await renderMinistrySongContext(currentSong.id,{networkNotes:false});toast(appText('Datos del ministerio guardados.','Ministry details saved.'))}catch(error){console.warn('[La Grey] No se pudieron guardar los datos del ministerio',error);toast(appText('No se pudieron guardar los cambios.','Could not save changes.'))}finally{if(button)button.disabled=false}}
function bindCloudState(){if(cloudStateUnsubscribe||!window.LAGREY_CLOUD?.subscribe)return;cloudStateUnsubscribe=window.LAGREY_CLOUD.subscribe(next=>{updateMinistryHome();updateMyRouteHome();if(next?.mode==='ministry'){pullMinistryRepertoire({rerender:true});pullMinistryEvents({rerender:true});syncPersonalFavorites();syncMyRoute();syncPersonalSongNotes({pull:false});syncActiveSetlistPreparation()}else{activateFavoriteContext(null);calendarCloudAvailable=null;updateCalendarMode();updateMyRouteHome();renderCalendar();if(lastSongList==='repertoire'&&!$('listing')?.classList.contains('hidden'))renderSongList([]);if(currentSong&&!$('detail')?.classList.contains('hidden'))renderMinistrySongContext(currentSong.id,{networkNotes:false})}if(currentSong&&!$('detail')?.classList.contains('hidden'))renderPersonalSongNotes(currentSong.id)})}
window.addEventListener('lagrey:cloud-ready',()=>{bindCloudState();pullMinistryRepertoire({rerender:true});pullMinistryEvents({rerender:true});syncPersonalFavorites();syncMyRoute();syncPersonalSongNotes({pull:false});syncActiveSetlistPreparation()});
window.addEventListener('lagrey:cloud-reboot',()=>setTimeout(()=>{bindCloudState();pullMinistryRepertoire({rerender:true});pullMinistryEvents({rerender:true});syncPersonalFavorites();syncMyRoute();syncPersonalSongNotes({pull:false});syncActiveSetlistPreparation()},80));
document.addEventListener('lagrey:profile-changed',()=>setTimeout(()=>{calendarCloudAvailable=null;updateMinistryHome();updateMyRouteHome();pullMinistryRepertoire({rerender:true});pullMinistryEvents({rerender:true});syncPersonalFavorites();syncMyRoute();syncPersonalSongNotes({pull:false});syncActiveSetlistPreparation();if(currentSong&&!$('detail')?.classList.contains('hidden'))renderPersonalSongNotes(currentSong.id)},100));
window.addEventListener('online',()=>{pullMinistryRepertoire({rerender:true});pullMinistryEvents({rerender:true});syncPersonalFavorites();syncMyRoute();syncPersonalSongNotes({pull:false});syncActiveSetlistPreparation()});
function showChords(){showView('chordsView');renderRootFilters();renderChordCatalog()}function renderRootFilters(){const r=['Todos',...CH.NOTES_SHARP];$('rootFilters').innerHTML=r.map(x=>`<button class="chip ${x==='Todos'?'active':''}" data-root="${x}">${x==='Todos'?appText('Todos','All'):notation==='latin'?ROOT_LATIN[x]:x}</button>`).join('');$('rootFilters').querySelectorAll('[data-root]').forEach(b=>b.onclick=()=>{$$('button[data-root]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderChordCatalog(b.dataset.root)})}
function renderChordCatalog(root='Todos'){const q=$('chordSearch').value.trim().toLowerCase(),items=CH.catalog().filter(c=>(root==='Todos'||c.root===root)&&(!q||(c.symbol+' '+CH.latin(c.symbol)+' '+c.label).toLowerCase().includes(q)));$('chordCatalog').innerHTML=items.map(c=>`<button class="chord-card" data-chord="${c.symbol}"><b>${esc(displayChord(c.symbol))}</b><small>${esc(appChordQuality(c.label))}</small><small>${esc(c.notes.map(n=>notation==='latin'?ROOT_LATIN[n]:n).join(' · '))}</small></button>`).join('');$('chordCatalog').querySelectorAll('[data-chord]').forEach(b=>b.onclick=()=>openChord(b.dataset.chord))}
function openChord(symbol){const instrument=preferredChordInstrument();chordState={symbol:normalizeChordToken(symbol),instrument,guitarIndex:0,pianoIndex:0};$('chordModalTitle').textContent=displayChord(chordState.symbol);const p=CH.parseChord(chordState.symbol),quality=appChordQuality(CH.QUALITY_LABELS[p?.quality]||p?.quality||'Mayor');$('chordModalSub').textContent=p?`${quality}${p.bass?` · ${appText('bajo','bass')} `+(notation==='latin'?ROOT_LATIN[p.bass]:p.bass):''}`:'';$('chordModal').classList.remove('hidden');selectChordInstrument(instrument)}
function selectChordInstrument(k){chordState.instrument=k;$('guitarTab').classList.toggle('active',k==='guitar');$('pianoTab').classList.toggle('active',k==='piano');$('guitarPanel').classList.toggle('hidden',k!=='guitar');$('pianoPanel').classList.toggle('hidden',k!=='piano');k==='guitar'?renderGuitar():renderPiano()}
function renderGuitar(){const v=CH.guitarVariations(chordState.symbol);if(!v.length){$('guitarVariants').innerHTML='';$('diagramSvg').innerHTML=`<text x="180" y="185" text-anchor="middle" font-size="17" fill="#6b7785">${appText('Posición de guitarra pendiente','Guitar position pending')}</text>`;return}chordState.guitarIndex=Math.min(chordState.guitarIndex,v.length-1);$('guitarVariants').innerHTML=v.map((x,i)=>`<button class="chip ${i===chordState.guitarIndex?'active':''}" data-gvar="${i}">${esc(appGuitarVariant(x.label||`Posición ${i+1}`))}</button>`).join('');$('guitarVariants').querySelectorAll('[data-gvar]').forEach(b=>b.onclick=()=>{chordState.guitarIndex=Number(b.dataset.gvar);renderGuitar()});drawGuitar($('diagramSvg'),v[chordState.guitarIndex])}
function drawGuitar(svg,d){const f=d.frets,fi=d.fingers||[],nums=f.filter(v=>typeof v==='number'&&v>0);let base=1;if(nums.length&&Math.min(...nums)>1)base=Math.min(...nums);const fc=5,l=60,t=78,sg=48,fg=48,r=l+sg*5;let s='<rect x="0" y="0" width="360" height="380" rx="16" fill="#fafbfc"/>';for(let i=0;i<6;i++){const x=l+i*sg;s+=`<text x="${x}" y="28" text-anchor="middle" font-size="13" fill="#6b7785">${6-i}</text><line x1="${x}" y1="${t}" x2="${x}" y2="${t+fg*fc}" stroke="#485460" stroke-width="1.5"/>`;if(f[i]==='x')s+=`<text x="${x}" y="61" text-anchor="middle" font-size="23" fill="#6b7785">×</text>`;else if(f[i]===0)s+=`<circle cx="${x}" cy="54" r="8" fill="none" stroke="#075f91" stroke-width="2.5"/>`}for(let j=0;j<=fc;j++){const y=t+j*fg;s+=`<line x1="${l}" y1="${y}" x2="${r}" y2="${y}" stroke="#485460" stroke-width="${j===0&&base===1?5:1.4}"/>`}if(base>1)s+=`<text x="23" y="${t+30}" text-anchor="middle" font-size="14" font-weight="700" fill="#6b7785">${base}fr</text>`;for(let i=0;i<6;i++){const fret=f[i];if(typeof fret!=='number'||fret<=0)continue;const rel=fret-base;if(rel<0||rel>=fc)continue;const x=l+i*sg,y=t+(rel+.5)*fg;s+=`<circle cx="${x}" cy="${y}" r="17" fill="#17324d"/>`;const finger=fi[i];if(finger!==''&&finger!=null)s+=`<text x="${x}" y="${y+5}" text-anchor="middle" font-size="14" font-weight="800" fill="white">${finger}</text>`}s+=`<text x="180" y="354" text-anchor="middle" font-size="14" fill="#6b7785">${appText('6ª cuerda ← guitarra → 1ª cuerda','6th string ← guitar → 1st string')}</text>`;svg.innerHTML=s}
function renderPiano(){const v=CH.inversions(chordState.symbol);if(!v.length)return;chordState.pianoIndex=Math.min(chordState.pianoIndex,v.length-1);$('pianoInversions').innerHTML=v.map((x,i)=>`<button class="chip ${i===chordState.pianoIndex?'active':''}" data-pinv="${i}">${esc(appInversionLabel(x.label))}</button>`).join('');$('pianoInversions').querySelectorAll('[data-pinv]').forEach(b=>b.onclick=()=>{chordState.pianoIndex=Number(b.dataset.pinv);renderPiano()});const c=v[chordState.pianoIndex],notes=c.notes;$('pianoNotes').textContent=notes.map(n=>notation==='latin'?ROOT_LATIN[n]:n).join('  ·  ')+(c.bass?`   | ${appText('Bajo:','Bass:')} ${notation==='latin'?ROOT_LATIN[c.bass]:c.bass}`:'');drawPiano($('pianoSvg'),notes,c.bass);$('pianoFingers').innerHTML=notes.length===3?appText('<b>Digitación sugerida:</b> mano derecha 1–3–5 · mano izquierda 5–3–1.','<b>Suggested fingering:</b> right hand 1–3–5 · left hand 5–3–1.'):notes.length===4?appText('<b>Digitación sugerida:</b> mano derecha 1–2–3–5 · mano izquierda 5–3–2–1.','<b>Suggested fingering:</b> right hand 1–2–3–5 · left hand 5–3–2–1.'):appText('Ajusta la digitación según la inversión y el contexto musical.','Adjust the fingering according to the inversion and musical context.')}
function drawPiano(svg,a,bass){const w=['C','D','E','F','G','A','B'],bl={C:'C#',D:'D#',F:'F#',G:'G#',A:'A#'},W=50,H=190;let s='<rect width="700" height="250" rx="15" fill="#f5f7f9"/>';for(let o=0;o<2;o++)w.forEach((n,i)=>{const x=(o*7+i)*W,is=a.includes(n);s+=`<rect x="${x}" y="20" width="${W}" height="${H}" fill="${is?'#9ec9e5':'white'}" stroke="#49535c"/><text x="${x+25}" y="235" text-anchor="middle" font-size="12" fill="#52606d">${notation==='latin'?ROOT_LATIN[n]:n}</text>`});for(let o=0;o<2;o++)w.forEach((n,i)=>{const bn=bl[n];if(!bn)return;const x=(o*7+i+1)*W-16,is=a.includes(bn);s+=`<rect x="${x}" y="20" width="32" height="115" rx="2" fill="${is?'#2f7faa':'#20252a'}"/><text x="${x+16}" y="151" text-anchor="middle" font-size="10" fill="#52606d">${notation==='latin'?ROOT_LATIN[bn]:bn}</text>`});if(bass)s+=`<text x="350" y="16" text-anchor="middle" font-size="12" fill="#7a5b1a">${appText('Bajo:','Bass:')} ${notation==='latin'?ROOT_LATIN[bass]:bass}</text>`;svg.innerHTML=s}
function tunerStringLabel(x){if(x.id==='auto')return'Auto';let label=notation==='latin'?x.label.replace(/[A-G][0-9]/,x.latin):x.label;if(appLang()==='en')label=label.replace(/^6ª/,'6th').replace(/^5ª/,'5th').replace(/^4ª/,'4th').replace(/^3ª/,'3rd').replace(/^2ª/,'2nd').replace(/^1ª/,'1st');return label}
function showTuner(){showView('tunerView');renderStringTargets()}function renderStringTargets(){const all=[{id:'auto',label:'Auto',latin:'Auto'},...GUITAR_STRINGS];$('stringTargets').innerHTML=all.map(x=>`<button class="string-btn ${(tuner.target?.id||'auto')===x.id?'active':''}" data-target="${x.id}">${tunerStringLabel(x)}</button>`).join('');$('stringTargets').querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{tuner.target=b.dataset.target==='auto'?null:GUITAR_STRINGS.find(x=>x.id===b.dataset.target);renderStringTargets()})}
function setTunerMode(m){tuner.mode=m;$$$('[data-tuner-mode]').forEach(b=>b.classList.toggle('active',b.dataset.tunerMode===m));$('stringTargets').classList.toggle('hidden',m!=='guitar');if(m==='chromatic')tuner.target=null;renderStringTargets()}
async function startTuner(){try{tuner.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});tuner.ctx=new(window.AudioContext||window.webkitAudioContext)();await tuner.ctx.resume();const src=tuner.ctx.createMediaStreamSource(tuner.stream);tuner.analyser=tuner.ctx.createAnalyser();tuner.analyser.fftSize=4096;tuner.buffer=new Float32Array(tuner.analyser.fftSize);src.connect(tuner.analyser);$('startTunerBtn').classList.add('hidden');$('stopTunerBtn').classList.remove('hidden');$('tunerAdvice').textContent=appText('Escuchando… toca una cuerda.','Listening… play a string.');tunerLoop()}catch(e){$('tunerAdvice').textContent=appText('No pude acceder al micrófono. Revisa el permiso del navegador.','I could not access the microphone. Check your browser permission.');toast(appText('Necesito permiso de micrófono para afinar','Microphone permission is required to tune'))}}
function stopTuner(){if(tuner.raf)cancelAnimationFrame(tuner.raf);tuner.stream?.getTracks().forEach(t=>t.stop());tuner.ctx?.close();Object.assign(tuner,{ctx:null,stream:null,analyser:null,raf:null,buffer:null});$('startTunerBtn').classList.remove('hidden');$('stopTunerBtn').classList.add('hidden');$('tunerNote').textContent='--';$('tunerHz').textContent=appText('Toca una cuerda','Play a string');$('meterNeedle').style.left='50%';$('tunerAdvice').textContent=appText('Afinador detenido.','Tuner stopped.')}
function autoCorrelate(buf,sr){let rms=0;for(let i=0;i<buf.length;i++)rms+=buf[i]*buf[i];rms=Math.sqrt(rms/buf.length);if(rms<.012)return-1;let r1=0,r2=buf.length-1,th=.2;for(let i=0;i<buf.length/2;i++){if(Math.abs(buf[i])<th){r1=i;break}}for(let i=1;i<buf.length/2;i++){if(Math.abs(buf[buf.length-i])<th){r2=buf.length-i;break}}const b=buf.slice(r1,r2),c=new Array(b.length).fill(0);for(let lag=0;lag<b.length;lag++){let sum=0;for(let i=0;i<b.length-lag;i++)sum+=b[i]*b[i+lag];c[lag]=sum}let d=0;while(d+1<c.length&&c[d]>c[d+1])d++;let max=-1,pos=-1;for(let i=d;i<c.length;i++)if(c[i]>max){max=c[i];pos=i}if(pos<=0)return-1;let T=pos,x1=c[T-1]||0,x2=c[T],x3=c[T+1]||0,a=(x1+x3-2*x2)/2,beta=(x3-x1)/2;if(a)T-=beta/(2*a);return sr/T}
