  const list=event.setlist||[],done=academyDone(setlistPrepTrack(event.id)),readyCount=list.filter(x=>done.has(setlistPrepItem(x.songId))).length,pct=list.length?Math.round(readyCount/list.length*100):0;
  if(!list.length){$('setlistSongs').innerHTML=`<p class="muted">${appText('Este evento no tiene canciones.','This event has no songs.')}</p>`;return}
