  const rows=list.map((x,i)=>{const s=songs.find(y=>y.id===x.songId),ready=done.has(setlistPrepItem(x.songId));return`<div class="setlist-prep-row${ready?' ready':''}"><button class="song setlist-prep-open" type="button" data-event-song="${s?.id}"><span><b>${i+1}. ${esc(s?.title||appText('Canción','Song'))}</b><br><small class="muted">${esc(s?.artist||'')}</small></span><span class="tone">${esc(displayTone(x.tone||s?.tone||''))}</span></button><button class="btn setlist-ready-btn ${ready?'academy-complete-on':''}" type="button" data-setlist-ready="${s?.id}">${ready?'✓ '+appText('Preparada','Prepared'):'○ '+appText('Por preparar','To prepare')}</button></div>`}).join('');
