const academyPick=value=>Array.isArray(value)?value[appLang()==='en'?1:0]:String(value||'');
let academyActiveTrack=null;
const academyUserId=()=>{const state=cloudState();if(state?.mode==='ministry'&&state.user?.id)return String(state.user.id);const p=savedAppProfile();return p?.cloud&&p?.id?String(p.id):''};
const academyProgressKey=trackId=>`lagrey_learning_progress_${academyUserId()||'guest'}_${trackId}`,academyDirtyKey=(userId,trackId)=>`lagrey_learning_dirty_${userId}_${trackId}`,academyMigratedKey=(userId,trackId)=>`lagrey_learning_migrated_${userId}_${trackId}`;
function academyDone(trackId){return new Set((readLocalJSON(academyProgressKey(trackId),[])||[]).map(String))}
function academySaveDone(trackId,set){writeLocalJSON(academyProgressKey(trackId),[...set])}
function academyVoiceCount(){const p=readLocalJSON('lagrey_academy_voice_progress_v1',{});return Array.isArray(p?.completed)?p.completed.length:0}
function academyCourseCount(course){return course.voice?academyVoiceCount():academyDone(course.id).size}
function academyPreferredInstrument(){const p=savedAppProfile();if(!p||p.id==='visitor')return'';if(['voice','piano','guitar','bass','drums'].includes(p.instrument))return p.instrument;const roles=Array.isArray(p.musicRoles)?p.musicRoles:[];return['voice','piano','guitar','bass','drums'].find(x=>roles.includes(x))||''}
function academySortedCourses(){const pref=academyPreferredInstrument();return ACADEMY_COURSES.slice().sort((a,b)=>(a.instrument===pref?-1:0)-(b.instrument===pref?-1:0))}
function academyProgressBar(done,total){const pct=total?Math.round(done/total*100):0;return `<div class="academy-mini-progress"><span style="width:${pct}%"></span></div><small>${done}/${total} · ${pct}%</small>`}
function renderAcademyCourses(){const grid=$('academyGrid');if(!grid)return;grid.innerHTML=academySortedCourses().map(course=>{const total=course.total||course.lessons?.length||0,done=Math.min(total,academyCourseCount(course)),recommended=course.instrument===academyPreferredInstrument();return`<button class="academy-course-card${recommended?' recommended':''}" data-academy-course="${course.id}"><span class="academy-course-icon">${course.icon}</span><span class="academy-course-copy"><small class="academy-level">${academyPick(course.level)}${recommended?' · '+appText('Para ti','For you'):''}</small><b>${academyPick(course.title)}</b><span>${academyPick(course.summary)}</span>${academyProgressBar(done,total)}</span><span class="academy-course-chevron">›</span></button>`}).join('');grid.querySelectorAll('[data-academy-course]').forEach(b=>b.onclick=()=>openAcademyCourse(b.dataset.academyCourse))}
function academyResourceButton(resource){if(!resource)return'';const label=resource==='repertoire'?appText('Abrir repertorio','Open repertoire'):resource==='tuner'?appText('Abrir afinador','Open tuner'):appText('Abrir acordes','Open chords');return`<button class="btn" data-academy-resource="${resource}">${resource==='repertoire'?'📖':resource==='tuner'?'🎤':'🎸🎹'} ${label}</button>`}
function renderAcademyCourse(course){const panel=$('academyCoursePanel');if(!panel||!course||course.voice)return;academyActiveTrack=course.id;const done=academyDone(course.id),count=done.size,total=course.lessons.length;panel.classList.remove('hidden');panel.innerHTML=`<div class="academy-track-head"><button class="btn" data-academy-courses>← ${appText('Rutas','Courses')}</button><div><span class="academy-level">${academyPick(course.level)}</span><h2>${course.icon} ${academyPick(course.title)}</h2><p>${academyPick(course.summary)}</p></div><div class="academy-track-total">${academyProgressBar(count,total)}</div></div><div class="academy-lessons">${course.lessons.map((lesson,i)=>{const complete=done.has(lesson.id);return`<article class="academy-lesson${complete?' completed':''}"><div class="academy-lesson-number">${complete?'✓':String(i+1).padStart(2,'0')}</div><div class="academy-lesson-body"><h3>${academyPick(lesson.title)}</h3><p><b>${appText('Objetivo:','Goal:')}</b> ${academyPick(lesson.goal)}</p><p><b>${appText('Práctica:','Practice:')}</b> ${academyPick(lesson.practice)}</p><p class="academy-ready"><b>${appText('Listo para seguir cuando:','Ready to continue when:')}</b> ${academyPick(lesson.ready)}</p><div class="academy-lesson-actions"><button class="btn ${complete?'academy-complete-on':'primary'}" data-academy-toggle="${lesson.id}">${complete?'✓ '+appText('Completada','Completed'):'○ '+appText('Marcar completada','Mark completed')}</button>${academyResourceButton(lesson.resource)}</div></div></article>`}).join('')}</div>`;panel.querySelector('[data-academy-courses]').onclick=()=>{panel.classList.add('hidden');academyActiveTrack=null;renderAcademyCourses();window.scrollTo({top:0,behavior:'smooth'})};panel.querySelectorAll('[data-academy-toggle]').forEach(b=>b.onclick=()=>toggleAcademyLearningItem(course.id,b.dataset.academyToggle));panel.querySelectorAll('[data-academy-resource]').forEach(b=>b.onclick=()=>openAcademyResource(b.dataset.academyResource));panel.scrollIntoView({behavior:'smooth',block:'start'})}
function openAcademyResource(resource){if(resource==='chords')showChords();else if(resource==='tuner')showTuner();else if(resource==='repertoire'){if(currentMinistryId())navigate('repertoire');else showSongList('cantos')}}
function openVoiceAcademy(){const trigger=document.querySelector('#home [data-open="voice"]');if(trigger){trigger.click();setTimeout(()=>document.querySelector('[data-academy-title]')?.scrollIntoView({behavior:'smooth',block:'start'}),120)}}
async function syncLearningTrack(trackId,onRefresh=null){const state=cloudState(),userId=state?.user?.id?String(state.user.id):'';if(state?.mode!=='ministry'||!userId||!state.data?.getLearningProgress||!state.data?.setLearningItemCompleted)return;try{let rows=await state.data.getLearningProgress(trackId),cloud=new Set(rows.map(x=>String(x.itemId))),local=academyDone(trackId),dirty=readLocalJSON(academyDirtyKey(userId,trackId),{}),migrated=localStorage.getItem(academyMigratedKey(userId,trackId))==='1';if(!migrated){for(const id of local)if(!cloud.has(id))await state.data.setLearningItemCompleted(trackId,id,true);localStorage.setItem(academyMigratedKey(userId,trackId),'1');rows=await state.data.getLearningProgress(trackId);cloud=new Set(rows.map(x=>String(x.itemId)))}const changes=Object.entries(dirty||{});if(changes.length){for(const [id,on] of changes)await state.data.setLearningItemCompleted(trackId,id,!!on);localStorage.removeItem(academyDirtyKey(userId,trackId));rows=await state.data.getLearningProgress(trackId);cloud=new Set(rows.map(x=>String(x.itemId)))}academySaveDone(trackId,cloud);if(typeof onRefresh==='function')onRefresh()}catch(error){console.warn('[La Grey aprendizaje] sincronización omitida',trackId,error)}}
async function syncAcademyTrack(trackId){const course=ACADEMY_COURSES.find(x=>x.id===trackId);if(!course||course.voice)return;return syncLearningTrack(trackId,()=>{if(!$('academyView')?.classList.contains('hidden')){renderAcademyCourses();if(academyActiveTrack===trackId)renderAcademyCourse(course)}})}
function toggleAcademyLearningItem(trackId,itemId){const done=academyDone(trackId),next=!done.has(itemId);next?done.add(itemId):done.delete(itemId);academySaveDone(trackId,done);const userId=academyUserId();if(userId){const dirty=readLocalJSON(academyDirtyKey(userId,trackId),{});dirty[itemId]=next;writeLocalJSON(academyDirtyKey(userId,trackId),dirty)}const course=ACADEMY_COURSES.find(x=>x.id===trackId);renderAcademyCourses();renderAcademyCourse(course);syncAcademyTrack(trackId)}
function openAcademyCourse(trackId){const course=ACADEMY_COURSES.find(x=>x.id===trackId);if(!course)return;if(course.voice){openVoiceAcademy();return}renderAcademyCourse(course);syncAcademyTrack(trackId)}
function showAcademy(){showView('academyView');academyActiveTrack=null;$('academyTitle').textContent=appText('Aprende para servir mejor','Learn to serve better');$('academyIntro').textContent=appText('Rutas prácticas que te llevan desde fundamentos hasta el repertorio real de tu ministerio.','Practical tracks that take you from foundations to your ministry’s real repertoire.');$('academyCoursePanel').classList.add('hidden');renderAcademyCourses();const state=cloudState();if(state?.mode==='ministry')ACADEMY_COURSES.filter(x=>!x.voice).forEach(x=>syncAcademyTrack(x.id))}
window.LAGREY_REFRESH_ACADEMY_I18N=()=>{if(!$('academyView')?.classList.contains('hidden')){renderAcademyCourses();if(academyActiveTrack){const course=ACADEMY_COURSES.find(x=>x.id===academyActiveTrack);if(course)renderAcademyCourse(course)}}};
